local _, WFJ = ...
WFJ.Data.add("quest", {
  [88756] = { "Riportare il botto", "Recupera $N1 ⟦Stolen Explosives=Esplosivi Rubati⟧ dagli accampamenti dei nani Ferroscuro.", "I Ferroscuro hanno qualche accampamento a est di qui, sul ⟦Direforge Hill=Colle Forgiatroce⟧, e hanno rubato un bel po' d'esplosivi dal nostro cantiere e se li son portati nelle tende.\n\nNon c'è bisogno che ti dica che razza di guai possono combinare i Ferroscuro con un barile di polvere!\n\nLo so che i Ferroscuro son pericolosi, ma ci servono quei barili. Li distingui dagli altri per i segni rossi che ci son sopra. Non possiamo lasciarli ai Ferroscuro!", "Questa guerra contro i Ferroscuro va avanti all'infinito!", "Ach, mi togli un bel peso dalla testa. Almeno i Ferroscuro non potranno lanciare un carro-bomba contro i nostri carri... o scagliarli con un trabucco... o farli rotolare giù dalla collina contro di noi... o darli in pasto alle melme e poi lasciarle libere vicino al nostro campo e dar fuoco a tutto.\n\nOra dobbiamo solo assicurarci che la polvere resti asciutta!\n\nGrazie!", 0xc57287cb, 0x0a061175, 0xf19bd9f0, 0x0d40ddf5, 0xce23de7c, "....." },
  [88757] = { "Effetti smarriti", "Riporta Essene's Necklace, ⟦Essene's Spellbook=Grimorio di Essene⟧ ed ⟦Essene's Waterskin=Borraccia di Essene⟧.", "Mentre fuggivo da quei Ferroscuro, ho finito per perdere un sacco della mia roba!\n\nPare che io abbia perso... la mia borraccia di cuoio verde, il mio libro degli incantesimi, la mia collana e... be', queste cose mi servono!\n\nSe riesci a trovarle mentre rifaccio i bagagli e riprendo fiato, mi saresti di grande aiuto.", nil, nil, 0xb1b07501, 0x8dd0b2c0, 0xd5dd92b9, nil, nil, "...mm" },
  [88758] = { "Sentimenti smarriti", "Riporta il biglietto di Essene a Corma Villard.", "Devo solo finire di rifare i bagagli e poi posso andarmene da qui!\n\nSe vuoi farmi un ultimo favore, ecco: porta questo biglietto a Corma. Così saprà che sono viva e che sto arrivando!", nil, nil, 0x4c47fdf9, 0x12fd10da, 0x3d2951ce, nil, nil, "...mm" },
  [88807] = { "Massacro degli Sferzarabbia", "Uccidi 8 Guerriero Sferzarabbia e 8 Urlatrice Sferzarabbia per il Comandante Cantovero ad Azshara.", "Azshara può sembrare bellissima, ma è un luogo maledetto. Orrori giacciono nel profondo delle sue acque, in attesa di emergere e dilaniare il mondo.\n\nTutto ciò che possiamo fare per ora è combattere gli orrori già emersi.\n\nI naga Sferzarabbia occupano le ⟦Ruins of Eldarath=Rovine di Eldarath⟧ a nordest. Quelli all'interno delle rovine sono ben fortificati, quindi dobbiamo prima eliminare i più deboli alla periferia.\n\nCome vedi, un altro combattente ci farebbe sempre comodo, se te la senti.", nil, nil, 0x98f4f1f6, 0xf567af16, 0xc3e0fca0, nil, nil, "...mm" },
  [88809] = { "La salvaguardia di Eldarath", "Raccogli $N1 Reliquia di Eldarath da Guardiaserpe Sferzarabbia, Sirena Sferzarabbia e Mirmidone Sferzarabbia, e la Testa di Sire Sarthiss, per il Comandante Cantovero ad Azshara.", "Millenni fa, Eldarath era uno spettacolo da ammirare: una testimonianza vivente della gloria e della potenza dei kaldorei. Quella che oggi chiamiamo Eldarath, al confronto, è appena un cumulo di macerie.\n\nCiononostante, ciò che resta merita di essere recuperato, anche solo per preservare la nostra storia. Gli Sferzarabbia vanno cacciati prima che Eldarath venga saccheggiata del tutto.\n\nSeguendo la strada verso nordest arriverai dritto nel cuore delle rovine. Vai là e recupera quante più nostre reliquie puoi... e la testa del loro comandante.", nil, nil, 0x3265e3cf, 0xdeed3688, 0x0fbfead7, nil, nil, "...mm" },
  [88812] = { "La riconquista di Crinocorvo", "Uccidi 5 Maestro di Guerra Sferzarabbia, 5 Incantatrice Sferzarabbia e annulla le 3 Pietre del Potere Naga vicino al ⟦Ravencrest Monument=Colosso di Crinocorvo⟧ per il Comandante Cantovero ad Azshara.", "Temo che il tempo possa presto dimenticare la casata kaldorei dei Crinocorvo. Un solo monumento in rovina è l'unica prova sopravvissuta della loro presenza qui.\n\nIl monumento si trova in cima alle scogliere, proprio all'estremità della penisola meridionale. Le incantatrici Sferzarabbia lì hanno una serie di pietre del potere con cui incanalano la loro magia. Prendi questa protezione e annullale. Questo paralizzerà la magia degli Sferzarabbia e ci darà un vantaggio per cacciarli.\n\nGià che ci sei, assicurati di eliminare qualche naga di persona.", nil, nil, 0x50486909, 0xe255d01f, 0xb035309c, nil, nil, "...mm" },
  [88813] = { "La testa del serpente", "Porta la testa del Signore della Guerra Krellian al Comandante Cantovero ad Azshara.", "Il tuo ultimo bersaglio è il ⟦Warlord Krellian=Signore della Guerra Krellian⟧, il capo degli Sferzarabbia. Si nasconde dietro le sue guardie nel ⟦Temple of Zin-Malor=Tempio di Zin-Malor⟧, tra le rovine di Eldarath.\n\nTaglia la testa a Krellian e i suoi tirapiedi torneranno strisciando in mare per la paura. Allora, finalmente, Azshara apparterrà di nuovo ai kaldorei.", nil, nil, 0x44e98df6, 0xdc00b1b5, 0x90c557e5, nil, nil, "...mm" },
  [88821] = { "Stabilire un contatto", "Trova la donna kaldorei vista per l'ultima volta sulla Riva Infranta.", "Durante una ricognizione lungo le scogliere della Riva Infranta, una delle nostre sentinelle ha notato una donna kaldorei sulla spiaggia.\n\nChiaramente non fa parte della nostra spedizione e non aveva l'aspetto di una combattente. Mi chiedo dunque cosa possa fare in un luogo ostile come questo.\n\nSe puoi, cerca di entrare in contatto con lei. Vorrei sapere perché si trova qui e se i nostri interessi possano coincidere.\n\nL'ultima volta è stata vista sulla costa orientale, lungo il lato nord della ⟦Bay of Storms=Baia delle Tempeste⟧.", nil, nil, 0x491d89a5, 0x1f0a2682, 0x188a9d50, nil, nil, "...mm" },
  [88857] = { "Salvare una Sentinella", "Aiuta Keldara Lamasole a fuggire dall'⟦Haldarr Encampment=Accampamento di Haldarr⟧, poi parla con il Comandante Cantovero al ⟦Talrendis Point=Bivacco di Talrendis⟧.", "<La sentinella parla sottovoce>\n\nAscolta, {class}, prima che ci sentano. Sono una sentinella del ⟦Talrendis Point=Bivacco di Talrendis⟧. I satiri qui mi credono fuori combattimento, ma sto solo fingendo, in attesa del momento in cui abbasseranno la guardia e potrò scappare.\n\nIl tuo arrivo è forse proprio quel momento.\n\nAiutami a uscire di qui, ti va?", nil, nil, 0x20e50750, 0x312c117d, 0x92d6a27d, nil, nil, "...mm" },
  [88884] = { "Tavolette degli ⟦Highborne=Alti Nobili⟧", "Trova le tre tavolette degli Alti Nobili tra le rovine della ⟦Southridge Beach=Spiaggia Costa del Sud⟧, poi portale a Saria Lunachiara ad Azshara.", "Appena a sud di qui, lungo la spiaggia, ci sono alcune tavolette con scritti degli Alti Nobili. Documentano le indagini degli Alti Nobili sulle leggi e sui poteri dell'arcano.\n\nLe tavolette sono custodite in strutture simili a pagode, sorvegliate dai naga, quindi non oserei tentare di procurarmele di persona.\n\nPer fortuna ho trovato un nuovo assistente!\n\nAllora, che ne dici? Pensi di poter essere ancora utile nella ricerca del sapere?", nil, nil, 0x1c667b66, 0x7646c407, 0xac9c0bb0, nil, nil, "...mm" },
  [88917] = { "Saccheggiatori striscianti", "Trova il Bastone dell'Arcimago Selwyn tra le ⟦Ruins of Eldarath=Rovine di Eldarath⟧ e portalo a Saria Lunachiara ad Azshara.", "Sono qui in cerca di manufatti degli Alti Nobili. Potresti definire il mio lavoro una specie di archeologia.\n\nLe rovine di Eldarath, a ovest, ne custodiscono molti, anche se i naga le stanno saccheggiando proprio ora.\n\nUna naga chiamata ⟦Lady Sesspira=Dama Sesspira⟧ guida il saccheggio; senza dubbio tiene per sé i reperti migliori.\n\nSe la mia ricerca è corretta, credo che possa essere in possesso del bastone dell'arcimago Selwyn, un mago degli Alti Nobili caduto.\n\nHo bisogno del tuo aiuto per ottenere quel bastone, {race}. Gli studiosi come me non sono adatti al combattimento.", nil, nil, 0x09007138, 0x5bdffc14, 0x14d00c3a, nil, nil, "...mm" },
})
